# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_can_a import B,K
W=[
E('canonisation','/ˌkænənaɪˈzeɪʃən/','封圣；经典地位的确立〔英国英语常见拼写〕','同样是在谈“进入认可名单”这件事，只是沿用 canonise 一系的拼写。','对应 canonization；现代可关联 canonise + -ation，历史仍接拉丁 canonizatio。',K+[['拉丁 canonizatio → 英语 canonization／canonisation','正式认可、封圣这一行为']],'英式新闻中的 canonisation ceremony 是封圣仪式；学术文章中的 canonisation of a text 是文本被视作权威或经典的过程。重音移到后面的 -sation，不沿用 canonise 的首音节重音。','canonisation ceremony；the canonisation of a writer；literary canonisation。','canonisation 和 canonization 的拼写不同，含义相同；不要把其中一个误认为“非正式封圣”。',('The book traces the history of her canonisation.','这本书追溯了她被封圣的历史过程。'),('The study explores the canonisation of modernist poetry.','这项研究探讨了现代主义诗歌如何获得经典地位。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/canonization','https://www.etymonline.com/word/canonization']),
E('cannon','/ˈkænən/','大炮；火炮','从管子形状想起：炮身就像一根放大的金属管。','法语 canon 接意大利 cannone 大管子，上接 canna；并不是英语 can 加上 non。',B+[['意大利 cannone → 法语 canon','大管子 → 炮'],['英语 cannon','大炮、火炮']],'古老的城堡炮、船炮可以叫 cannon；现代语境中也有 aircraft cannon 机炮。a loose cannon 比喻行事难以控制、可能给同伴惹祸的人，像甲板上一门脱离固定位置的大炮。','fire a cannon；an old cannon；a loose cannon；复数可用 cannon 或 cannons。','cannon 大炮和 canon 规范、正典同音。历史上大炮义也写 canon，后来用双 n 更清楚地区分。',('An old cannon stands beside the castle gate.','城堡门旁立着一门旧炮。'),('His colleagues see him as a loose cannon in negotiations.','同事们觉得他谈判时难以控制，随时可能惹出麻烦。'),sources=['https://www.etymonline.com/word/cannon','https://www.oxfordlearnersdictionaries.com/definition/english/cannon_1']),
E('cannonball','英 /ˈkænənbɔːl/；美 /ˈkænənbɔl/','旧式球形炮弹；抱膝跳水动作','cannon 大炮 + ball 球：先是从炮里打出的圆球，后来也用来形容人缩成球砸进水里的样子。','英语 cannon + ball 的复合词；不是现代所有炮弹的通称。',B+[['cannone → cannon','大管子 → 大炮'],['cannon + ball → cannonball','炮用圆球 → 炮弹；球状入水动作']],'博物馆里的铁球形旧炮弹常叫 cannonball。泳池里 do a cannonball 是把身体蜷起来、抱住膝盖跳进水中，通常会溅起很大的水花。两个义项都能抓住圆球的形状。','an iron cannonball；fire a cannonball；do a cannonball。','shell 常指现代炮弹，cannonball 特指传统球形炮弹。泳池动作中的 ball 指蜷起的身体，不是抱着一颗球跳。',('The display included a cannonball recovered from the wreck.','展品里有一枚从沉船中打捞出的球形炮弹。'),('He did a cannonball into the pool and splashed everyone nearby.','他抱膝跳进泳池，把附近的人都溅湿了。'),sources=['https://en.wiktionary.org/wiki/cannonball','https://www.merriam-webster.com/dictionary/cannonball']),
E('canal','/kəˈnæl/','运河；沟渠；体内的管道','把“管子里有东西流过”放大到地面：挖出一条让水和船通过的路线。','法语 canal 接拉丁 canalis 水管、沟槽，通常追溯至 canna。',B+[['拉丁 canalis → 法语 canal','水管、沟槽'],['英语 canal','身体管道、水管 → 人工水道、运河']],'地图上的 canal 多指人为修建的水道；ear canal 是耳道。英语早期记录中有身体管道义，后来才出现今天熟悉的人工航道义，不能按现代常见程度倒排历史。','a shipping canal；an irrigation canal；the ear canal；a canal boat。','canal 常指人工水道，river 是天然河流。channel 还可指天然水道、海峡和抽象渠道，范围更广。',('The canal connects the river to the harbor.','这条运河把河流和港口连接起来。'),('The diagram shows the ear canal in cross section.','这张图展示了耳道的剖面。'),sources=['https://www.etymonline.com/word/canal','https://en.wiktionary.org/wiki/canal']),
E('channel','/ˈtʃænəl/','水道；海峡；渠道；频道；把某物引向某处','先想一条水槽，水沿着它流。后来水换成信息、钱、精力，通路就成了渠道。','古法语 chanel 接拉丁 canalis，与 canal 同源；动词由名词发展。不要拆成 chan + nel。',B+[['拉丁 canalis → 古法语 chanel','水管、沟槽、水道'],['英语 channel','水道 → 传递通路、频道；引导流向']],'a communication channel 是传递消息的渠道；a TV channel 是承载节目的频道。channel anger into art 是把愤怒导入创作，不任它四处乱撞。音乐评论中 channel a singer 还可以说模仿、再现那位歌手的风格。','through official channels；a news channel；channel energy into something；the English Channel。','canal 与 channel 是同源词，不是相同拼写的变体。channel energy 是引导精力，不是简单地“播放精力”。',('Please send the request through the official channel.','请通过正式渠道提交申请。'),('She channels her frustration into writing.','她把挫败感转化成写作的动力。'),('The boat followed a narrow channel between the islands.','船沿着岛屿之间一条狭窄的水道前进。'),sources=['https://www.etymonline.com/word/channel','https://www.oxfordlearnersdictionaries.com/definition/english/channel_2']),
E('channeling','/ˈtʃænəlɪŋ/','引导、输送；模仿某种风格〔常见美式拼写〕','把原本散开的东西引到一条明确的路上：钱流向项目，精力流向创作。','channel + -ing；美国英语通常不双写 l，对应 channelling。',B+[['canalis → chanel → channel','管道 → 引导通过某条路线'],['channeling','正在引导；输送这一过程']],'channeling funds into research 是把资金导向研究；channeling an old movie star 可以说在妆容、动作或表演上再现一位旧时代影星的风格。超自然语境另有通灵义，指声称让灵体借自己传话。','channeling money into something；channeling energy；channeling a performer。','普通工作语境中的 channeling 通常是引导资源，不要一看到这个词就解成通灵。',('The foundation is channeling more funds into local libraries.','基金会正把更多资金投入当地的图书馆。'),('In this role, she seems to be channeling a silent movie star.','演这个角色时，她仿佛在再现一位默片明星的神态。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/channel_2','https://en.wiktionary.org/wiki/channeling']),
E('channelling','/ˈtʃænəlɪŋ/','引导、输送；模仿风格〔常见英式拼写〕','给一种力量安排去处，让它顺着某个方向流动。','channel + -ing，按英国英语常见规则双写末尾 l；对应 channeling。',B+[['canalis → channel','水道 → 资源或信息通过的路径'],['channelling','引导流向；输送']],'channelling anger into exercise 是把愤怒的能量用在运动中；channelling aid through a charity 强调援助经由哪个机构送出。into 常接去处，through 常接中间渠道。','channelling energy into something；channelling aid through an organization。','channelling 与 channeling 同义，双 l 不表示动作更强。区分 into 的目的地和 through 的途径，比死记中文“输送”更实用。',('He is channelling his nervous energy into preparation.','他正把紧张带来的那股劲用在准备工作上。'),('The group is channelling donations through local charities.','这个组织正通过当地慈善机构转送捐款。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/channel_2','https://en.wiktionary.org/wiki/channelling']),
E('canyon','/ˈkænjən/','峡谷','想象地面被切出一道深而长的凹槽，人在里面像站在两堵高墙之间。','直接借自西班牙语 cañón；通常连到 caño 管及拉丁 canna，但更早的路线也有其他解释。',B+[['西班牙 caño／cañón','管；深槽、峡谷〔传统关联〕'],['英语 canyon','两侧陡峭的深谷']],'canyon 常让人想到陡壁夹出的深谷，尤其在美洲地理名称里。the Grand Canyon 是美国大峡谷。西班牙 ñ 的发音在英语里用 ny 表示，所以词中不是普通的 n 音。','a deep canyon；the canyon rim；the canyon floor；the Grand Canyon。','valley 是较宽泛的山谷；canyon 强调深而两侧陡峭。与 cannon 的传统远源有关，但英语 canyon 不是由 cannon 改拼而来。',('The river winds through a deep canyon.','河流蜿蜒穿过一条深深的峡谷。'),('We watched the sunset from the canyon rim.','我们站在峡谷边缘看日落。'),sources=['https://www.etymonline.com/word/canyon','https://en.wiktionary.org/wiki/canyon']),
E('cannelloni','英 /ˌkænəˈləʊni/；美 /ˌkænəˈloʊni/','意式大管面；填馅烤管面','看到一根根大面管，里面塞上肉、奶酪或蔬菜，就能记住这个菜名。','借自意大利 cannelloni，cannellone 的复数；cannello 是管子，最终接 canna。',B+[['意大利 cannello → cannellone／cannelloni','管子 → 大管子〔复数〕'],['英语 cannelloni','大型管状意面及其填馅菜肴']],'菜单上的 spinach and ricotta cannelloni 通常是菠菜乳清奶酪馅的烤管面。它的名称强调管形，不是规定只能塞一种馅。英语常把菜名整体作不可数名词使用。','stuffed cannelloni；spinach cannelloni；a dish of cannelloni。','cannelloni 是大管面；cannellini 常见于 cannellini beans，指一种白芸豆。两者拼写相近，但盘子里的东西不同。',('She filled the cannelloni with spinach and ricotta.','她把菠菜和乳清奶酪塞进大管面里。'),('The restaurant serves cannelloni baked in tomato sauce.','这家餐馆供应放在番茄酱里烤制的大管面。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/cannelloni','https://en.wiktionary.org/wiki/cannelloni'])
]
